GREEN='205944'; LIGHT='EAF4F0'; GRAY='F5F7F6'; GRID='D9D9D9'; TEXT=RGBColor(30,47,40)

def set_font(r,size=9.8,bold=False,color=TEXT):
    r.font.name='Arial'; r._element.rPr.rFonts.set(qn('w:ascii'),'Arial'); r._element.rPr.rFonts.set(qn('w:hAnsi'),'Arial'); r.font.size=Pt(size); r.bold=bold; r.font.color.rgb=color
def tx(p,s,**kw): r=p.add_run(s); set_font(r,**kw); return r
def shade(c,color):
    p=c._tc.get_or_add_tcPr(); n=p.find(qn('w:shd'))
    if n is None: n=OxmlElement('w:shd'); p.append(n)
    n.set(qn('w:fill'),color)
def cell_format(c):
    p=c._tc.get_or_add_tcPr(); b=p.first_child_found_in('w:tcBorders')
    if b is None: b=OxmlElement('w:tcBorders'); p.append(b)
    for e in ('top','left','bottom','right','insideH','insideV'):
        n=b.find(qn(f'w:{e}'))
        if n is None: n=OxmlElement(f'w:{e}'); b.append(n)
        n.set(qn('w:val'),'single'); n.set(qn('w:sz'),'8'); n.set(qn('w:color'),GRID)
    m=p.first_child_found_in('w:tcMar')
    if m is None: m=OxmlElement('w:tcMar'); p.append(m)
    for s in ('top','start','bottom','end'):
        n=m.find(qn(f'w:{s}'))
        if n is None: n=OxmlElement(f'w:{s}'); m.append(n)
        n.set(qn('w:w'),'105'); n.set(qn('w:type'),'dxa')
    c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
def add_table(doc,headers,rows,widths,small=False):
    t=doc.add_table(rows=1,cols=len(headers)); t.style='Table Grid'; t.autofit=False
    for i,h in enumerate(headers):
        c=t.rows[0].cells[i]; c.width=Cm(widths[i]); shade(c,GREEN); cell_format(c); p=c.paragraphs[0]; p.paragraph_format.space_after=Pt(0); tx(p,h,size=8.7 if small else 9.2,bold=True,color=RGBColor(255,255,255))
    pr=t.rows[0]._tr.get_or_add_trPr(); el=OxmlElement('w:tblHeader'); el.set(qn('w:val'),'true'); pr.append(el)
    for ri,row in enumerate(rows):
        cells=t.add_row().cells
        row_pr=t.rows[-1]._tr.get_or_add_trPr(); cant_split=OxmlElement('w:cantSplit'); row_pr.append(cant_split)
        for i,val in enumerate(row):
            c=cells[i]; c.width=Cm(widths[i]); shade(c,'FFFFFF' if ri%2==0 else GRAY); cell_format(c); p=c.paragraphs[0]; p.paragraph_format.space_after=Pt(0); p.paragraph_format.line_spacing=1.03; tx(p,str(val),size=8.25 if small else 8.7)
    p=doc.add_paragraph(); p.paragraph_format.space_after=Pt(2)
def heading(doc,s,l=1):
    p=doc.add_paragraph(style=f'Heading {l}'); p.paragraph_format.keep_with_next=True; p.paragraph_format.space_before=Pt(11 if l==1 else 7); p.paragraph_format.space_after=Pt(4); tx(p,s,size=14.5 if l==1 else 11.5,bold=True,color=RGBColor(0,0,0))
def body(doc,s,lead=None):
    p=doc.add_paragraph(); p.paragraph_format.space_after=Pt(6); p.paragraph_format.line_spacing=1.11
    if lead: tx(p,lead,bold=True)
    tx(p,s)
def bullet(doc,s):
    p=doc.add_paragraph(style='List Bullet'); p.paragraph_format.space_after=Pt(2); p.paragraph_format.line_spacing=1.05; tx(p,s)
def setup(doc):
    sec=doc.sections[0]; sec.orientation=WD_ORIENT.LANDSCAPE; sec.page_width=Cm(27.94); sec.page_height=Cm(21.59); sec.top_margin=Cm(1.25); sec.bottom_margin=Cm(1.25); sec.left_margin=Cm(1.4); sec.right_margin=Cm(1.4)
    f=sec.footer.paragraphs[0]; f.alignment=WD_ALIGN_PARAGRAPH.CENTER; f.paragraph_format.space_before=Pt(5); tx(f,'ИИ Наставник  |  Каталог ручной приёмки  |  Версия 0.24.20',size=8.1,color=RGBColor(100,112,106))
    st=doc.styles['Normal']; st.font.name='Arial'; st._element.rPr.rFonts.set(qn('w:ascii'),'Arial'); st._element.rPr.rFonts.set(qn('w:hAnsi'),'Arial'); st.font.size=Pt(9.8)
    for name in ('Title','Heading 1','Heading 2'):
        st=doc.styles[name]; st.font.name='Arial'; st._element.rPr.rFonts.set(qn('w:ascii'),'Arial'); st._element.rPr.rFonts.set(qn('w:hAnsi'),'Arial'); st.font.color.rgb=RGBColor(0,0,0)
    pp=doc.styles['Title']._element.get_or_add_pPr()
    for x in pp.findall(qn('w:pBdr')): pp.remove(x)

