def case_card(doc,case,p0=True):
    tid,uc,steps,expected,*tail=case; problem=tail[0] if tail else 'Зафиксируйте номер теста, фактический результат и обезличенное подтверждение.'
    if tid == 'TC-17':
        doc.add_page_break()
    p=doc.add_paragraph(); p.paragraph_format.keep_with_next=True; p.paragraph_format.space_before=Pt(7); p.paragraph_format.space_after=Pt(2); tx(p,f'{tid}  {uc}',size=10.5,bold=True,color=RGBColor(0,0,0)); tx(p,'   ☐ Пройден   ☐ Не пройден   ☐ Заблокирован   ☐ Нужно улучшить',size=8.5,color=RGBColor(78,91,84))
    add_table(doc,['Шаги','Ожидаемый результат','При проблеме записать'],[[steps,expected,problem]],[8.1,8.1,7.2],small=True)
def build():
    doc=Document(); setup(doc)
    if LOGO.exists():
        p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_after=Pt(4); p.add_run().add_picture(str(LOGO),width=Cm(1.85))
    p=doc.add_paragraph(style='Title'); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_after=Pt(5); tx(p,'Каталог ручной приёмки ИИ Наставника',size=23,bold=True,color=RGBColor(0,0,0))
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_after=Pt(12); tx(p,'Use cases и test cases для подготовки к Demo Day и пилоту',size=11.2,color=RGBColor(75,95,86))
    body(doc,'Этот документ помогает проверить реально реализованные функции до демонстрации: панель ИИ Наставника, двуязычные подсказки, вопросы, голос, озвучивание, риск сайта, ограниченный рекламный фильтр и Office Online. Начните с P0: это обязательный набор для доказательства основной ценности и безопасности.',lead='Назначение. ')
    add_table(doc,['Версия','Аудитория','Правило теста'],[['0.24.20','Начинающие, пожилые, дети под присмотром взрослых, RU и KK пользователи','Только тестовые страницы и синтетические данные; не вводить реальные пароли, коды, карты, документы или переписку.']],[3.0,7.5,12.9])
    heading(doc,'Как проводить проверку')
    for x in ['До старта запишите версию расширения, браузер, Windows, адрес backend и язык интерфейса.','Для ИИ-функций запустите backend, сохраните код подключения в popup и убедитесь, что модель доступна.','В каждой строке отметьте статус. При проблеме сохраните обезличенное описание, номер теста и скриншот без личных данных.','Успешная подсказка не доказывает завершение действия: наставник объясняет и подсвечивает, но не нажимает за человека.']: bullet(doc,x)
    doc.add_page_break()
    heading(doc,'1  Пользовательские сценарии')
    add_table(doc,['ID','Цель пользователя','Приоритет','Критерий пользы'],UC,[2.0,8.2,2.0,11.2],small=True)
    heading(doc,'Целевая модель доступа после хакатона',2)
    body(doc,'Сценарии UC-15–UC-18 описывают будущую production-модель и не являются реализованной частью версии 0.24.20. Для текущего хакатона проверяется pairing-токен в UC-12 и TC-25/TC-26.')
